/**
 * EDS Block: App
 * Generated by AEM Migration Agent
 * Behavior IR: App
 * Framework: vue
 */

import { moveInstrumentation } from '../../scripts/scripts.js';
import {
  setDefaultCurrency,
  renderApp,
} from '../shared-new/generated-jsx.js';
/* eslint-disable no-console */

export default async function decorate(block) {
  moveInstrumentation(block);
  if (block.dataset.blockName == null) block.dataset.blockName = 'App';
  setDefaultCurrency(block.dataset.currency || null);

  let data = null;
  let loading = true;
  let error = null;
  let retry = () => {};
  let editingId = null;
  let editForm = {};
  let createForm = {};

  const renderBlock = () => {
    block.replaceChildren();
    try {
      renderApp(block, {
        data,
        loading,
        error,
        retry,
        currency: block.dataset.currency || null,
        form: createForm,
        editingId,
        editForm,
      });
    } catch (err) {
      const p = document.createElement('p');
      p.textContent = `Render error: ${err instanceof Error ? err.message : String(err)}`;
      block.appendChild(p);
      console.error(err);
    }
  };

  const load = async () => {
    loading = true;
    error = null;
    renderBlock();
    try {
      const response = await fetch(block.dataset.dataSource || 'https://fakestoreapi.com/users');
      if (!response.ok) throw new Error(`HTTP ${response.status}`);
      data = await response.json();
    } catch (err) {
      error = err instanceof Error ? err.message : String(err);
    } finally {
      loading = false;
      renderBlock();
    }
  };

  // Orchestrator state machine: consumes the component's dispatched events and
  // replays the source script handlers (real API mutations when the component
  // used an API service, otherwise local model updates).
  const onComponentEvent = async (ev) => {
    const source = ev.detail?.event?.target;
    if (source && !block.contains(source)) return;
    const { name, args = [] } = ev.detail || {};
    if (name === 'startEdit') {
      const user = args[0];
      if (!user) return;
      editingId = user.id;
      editForm = { username: user.username ?? '', email: user.email ?? '', password: user.password ?? '' };
      renderBlock();
    } else if (name === 'saveEdit' && Array.isArray(data)) {
      const id = args[0];
      try {
        const response = await fetch(`${block.dataset.dataSource || 'https://fakestoreapi.com/users'}/${id}`, {
          method: 'PUT',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ id, ...editForm }),
        });
        if (!response.ok) throw new Error(`HTTP ${response.status}`);
        const updated = await response.json();
        data = data.map((u) => (u.id === id ? { ...u, ...updated } : u));
      } catch (err) {
        error = err instanceof Error ? err.message : String(err);
      }
      editingId = null;
      editForm = {};
      renderBlock();
    } else if (name === 'cancelEdit') {
      editingId = null;
      editForm = {};
      renderBlock();
    } else if (name === 'handleDelete' && Array.isArray(data)) {
      const id = args[0];
      try {
        const response = await fetch(`${block.dataset.dataSource || 'https://fakestoreapi.com/users'}/${id}`, {
          method: 'DELETE',
        });
        if (!response.ok) throw new Error(`HTTP ${response.status}`);
        data = data.filter((u) => u.id !== id);
      } catch (err) {
        error = err instanceof Error ? err.message : String(err);
      }
      if (editingId === id) { editingId = null; editForm = {}; }
      renderBlock();
    } else if (name === 'updateField') {
      const [field, value] = args;
      if (editingId != null) editForm = { ...editForm, [field]: value || '' };
      else createForm = { ...createForm, [field]: value || '' };
    } else if (name === 'handleSubmit') {
      const { username = '', email = '', password = '' } = createForm;
      if (!username || !email || !password) return;
      try {
        const response = await fetch(block.dataset.dataSource || 'https://fakestoreapi.com/users', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(createForm),
        });
        if (!response.ok) throw new Error(`HTTP ${response.status}`);
        const created = await response.json();
        data = [created, ...(Array.isArray(data) ? data : [])];
      } catch (err) {
        error = err instanceof Error ? err.message : String(err);
      }
      createForm = {};
      renderBlock();
    }
  };
  document.addEventListener('eds:component-event', onComponentEvent);

  retry = load;
  await load();
}
